@startuml

class OilWell {
  + code : string
}

abstract class OnshoreWell {
  + surfaceExtension : float
}

abstract class OffshoreWell {
  + installationYear : int
}

class Area {
  + code : string
  + environmentalImportance : int
}

class OilCompany {
  + taxCode : string
  + numberOfEmployees : int
}

class Extraction {
  + quantity : float
}

enum WellCategory {
  Onshore
  Offshore
}

OnshoreWell --|> OilWell
OffshoreWell --|> OilWell

OilWell "1" -- "0..*" Extraction
OilCompany "1" -- "0..*" Extraction
Extraction "1" -- "1" OilWell
Extraction "1" -- "1" OilCompany

OffshoreWell "0..1" -- "0..1" Area : locatedIn

@enduml

